  id,
  className,
  classNameArrow,
  variant = 'dark',
  anchorId,
  anchorSelect,
  place = 'top',
  offset = 10,
  events = ['hover'],
  positionStrategy = 'absolute',
  middlewares,
  wrapper: WrapperElement,
